<!doctype html>
<html lang="en" dir="ltr">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Riwaq | Real Estate Operations</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@600;700&family=Tajawal:wght@400;500;700&display=swap" rel="stylesheet">
    <style>
        :root { --ink:#20212a; --muted:#737683; --rose:#b46d86; --rose-dark:#914d67; --blush:#fdf5f6; --paper:#fffdfb; --line:#eee7e7; --sage:#527b70; --gold:#bd9557; --navy:#293845; }
        *{box-sizing:border-box} body{margin:0;background:#faf9f8;color:var(--ink);font:14px 'DM Sans','Tajawal',sans-serif} .shell{display:grid;grid-template-columns:255px 1fr;min-height:100vh}.sidebar{background:var(--paper);border-right:1px solid var(--line);padding:28px 16px;display:flex;flex-direction:column}.brand{display:flex;gap:11px;align-items:center;padding:0 10px 31px}.brand-mark{display:grid;place-items:center;width:38px;height:38px;border-radius:13px;background:linear-gradient(145deg,#c27c94,#8d4b64);color:white;font-family:Georgia;font-size:20px;box-shadow:0 8px 18px #b46d8633}.brand h1{font:700 20px 'Playfair Display',serif;margin:0;letter-spacing:-.5px}.brand small{color:var(--muted);font-size:10px;letter-spacing:1.2px;text-transform:uppercase}.nav-label{font-size:10px;letter-spacing:1.3px;color:#a4a1a5;padding:0 12px 10px;text-transform:uppercase}.nav a{display:flex;align-items:center;gap:11px;text-decoration:none;color:#676773;padding:11px 12px;border-radius:10px;margin:2px 0;font-weight:500}.nav a.active,.nav a:hover{background:var(--blush);color:var(--rose-dark)}.icon{width:18px;text-align:center;font-size:16px}.company-card{margin-top:auto;border:1px solid #f0dfdf;background:linear-gradient(145deg,#fff9f8,#fdf2f3);padding:15px;border-radius:14px}.company-card p{margin:0 0 4px;font-weight:700}.company-card span{color:var(--muted);font-size:12px}.main{padding:26px 38px 45px;max-width:1600px;width:100%;margin:auto}.topbar{display:flex;justify-content:space-between;align-items:center;margin-bottom:32px}.crumb{color:var(--muted);font-size:13px}.crumb strong{color:var(--ink)}.actions{display:flex;gap:10px;align-items:center}.lang,.avatar{border:1px solid var(--line);background:white;border-radius:9px;padding:9px 12px;color:#555;font:inherit}.avatar{background:#3e5061;color:white;border:0;width:38px;height:38px;padding:0;border-radius:50%;font-weight:700}.hero{background:radial-gradient(circle at 92% 18%,#f1d7d9,transparent 25%),linear-gradient(110deg,#293845,#364a59);border-radius:20px;padding:31px 34px;color:white;position:relative;overflow:hidden}.hero:after{content:'⌂';position:absolute;right:42px;bottom:-60px;color:#ffffff0f;font:260px Georgia}.hero p{color:#d7dfe3;margin:0 0 8px}.hero h2{font:700 32px 'Playfair Display',serif;letter-spacing:-.8px;margin:0 0 19px}.hero .date{display:inline-flex;align-items:center;gap:8px;border:1px solid #ffffff2d;background:#ffffff12;border-radius:20px;padding:8px 12px;color:#e7ecee;font-size:12px}.overview{display:grid;grid-template-columns:repeat(4,1fr);gap:15px;margin:24px 0}.metric{background:white;border:1px solid var(--line);border-radius:15px;padding:18px}.metric .label{display:flex;justify-content:space-between;color:var(--muted);font-size:12px}.metric b{display:block;font-size:25px;margin:10px 0 5px;letter-spacing:-.8px}.up{color:var(--sage);font-size:12px}.gold{color:var(--gold)}.content{display:grid;grid-template-columns:1.34fr .9fr;gap:20px}.panel{background:white;border:1px solid var(--line);border-radius:16px;padding:21px}.panel-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.panel-title h3{font-size:15px;margin:0}.panel-title a{color:var(--rose-dark);font-size:12px;text-decoration:none;font-weight:700}.flow{display:grid;grid-template-columns:repeat(5,1fr);gap:4px}.step{position:relative;padding:13px 8px 8px;text-align:center}.step:not(:last-child):after{content:'';position:absolute;right:-7px;top:28px;width:14px;border-top:1px dashed #d7cbcd}.dot{width:36px;height:36px;margin:auto auto 9px;display:grid;place-items:center;border-radius:50%;background:var(--blush);color:var(--rose-dark);font-weight:700}.step b{display:block;font-size:11px}.step span{display:block;color:var(--muted);font-size:10px;margin-top:4px}.list{padding:0;margin:0;list-style:none}.list li{display:flex;gap:12px;padding:12px 0;border-bottom:1px solid #f3eeee}.list li:last-child{border:0}.dot-status{width:9px;height:9px;border-radius:50%;margin-top:5px;background:var(--rose)}.dot-status.green{background:var(--sage)}.dot-status.gold{background:var(--gold)}.item-copy{flex:1}.item-copy b{display:block;font-size:13px}.item-copy span{color:var(--muted);font-size:12px}.pill{font-size:10px;border-radius:10px;padding:4px 8px;background:#fff3dc;color:#95651b;height:max-content}.quick{display:grid;grid-template-columns:1fr 1fr;gap:10px}.quick a{border:1px solid var(--line);border-radius:12px;padding:14px;text-decoration:none;color:var(--ink);transition:.2s}.quick a:hover{border-color:#dba5b5;transform:translateY(-2px)}.quick strong{display:block;font-size:12px;margin-top:8px}.quick span{color:var(--muted);font-size:11px}.quick-icon{font-size:20px}.company-row{display:flex;gap:9px;align-items:center;padding:11px 0;border-bottom:1px solid #f3eeee}.company-row:last-child{border:0}.company-badge{width:31px;height:31px;border-radius:9px;display:grid;place-items:center;color:white;font-weight:700;font-size:12px}.marketing{background:#bb7b88}.valuation{background:#aa8956}.realty{background:#527b70}.company-row b{font-size:12px;display:block}.company-row span{font-size:11px;color:var(--muted)}.status{margin-left:auto;font-size:11px;color:var(--sage);background:#eef7f4;padding:4px 7px;border-radius:8px}@media(max-width:900px){.shell{grid-template-columns:1fr}.sidebar{display:none}.main{padding:20px}.overview{grid-template-columns:repeat(2,1fr)}.content{grid-template-columns:1fr}.hero h2{font-size:26px}}@media(max-width:520px){.overview{grid-template-columns:1fr}.topbar{align-items:flex-start}.actions{gap:5px}.hero{padding:25px 20px}.flow{grid-template-columns:1fr}.step:not(:last-child):after{display:none}.step{display:flex;gap:12px;text-align:left;align-items:center}.dot{margin:0}.quick{grid-template-columns:1fr}}
    </style>
</head>
<body>
<div class="shell">
    <aside class="sidebar">
        <div class="brand"><div class="brand-mark">R</div><div><h1>Riwaq</h1><small>Real estate ERP</small></div></div>
        <div class="nav-label">Workspace</div>
        <nav class="nav"><a class="active" href="#"><span class="icon">⌘</span>Overview</a><a href="#"><span class="icon">♙</span>Leads & CRM</a><a href="#"><span class="icon">⌂</span>Properties</a><a href="#"><span class="icon">◈</span>Evaluations</a><a href="#"><span class="icon">▣</span>Sales & Rentals</a></nav>
        <div class="nav-label" style="margin-top:18px">Manage</div>
        <nav class="nav"><a href="#"><span class="icon">✉</span>Mail Centre</a><a href="#"><span class="icon">◷</span>Tasks & Viewings</a><a href="#"><span class="icon">◫</span>Finance</a><a href="#"><span class="icon">▤</span>Reports</a></nav>
        <div class="company-card"><p>Oman workspace</p><span>OMR · VAT-ready · English / العربية</span></div>
    </aside>
    <main class="main">
        <header class="topbar"><div class="crumb">Workspace / <strong>Executive overview</strong></div><div class="actions"><button class="lang">العربية</button><button class="lang">⌕</button><button class="avatar">SA</button></div></header>
        <section class="hero"><p>Good morning, Sarah</p><h2>Everything moving forward, beautifully.</h2><span class="date">◷ Sunday, 1 November 2026 · Muscat</span></section>
        <section class="overview"><div class="metric"><div class="label"><span>Active properties</span><span>⌂</span></div><b>{{ $activeProperties }}</b><span class="up">Available in your companies</span></div><div class="metric"><div class="label"><span>Open leads</span><span>♙</span></div><b>{{ $openLeads }}</b><span class="up">Requiring follow-up</span></div><div class="metric"><div class="label"><span>Outstanding collections</span><span>◫</span></div><b>OMR {{ number_format($outstandingCollections, 3) }}</b><span class="gold">Across active transactions</span></div><div class="metric"><div class="label"><span>Open valuations</span><span>◈</span></div><b>{{ $openValuations }}</b><span class="up">Awaiting completion</span></div></section>
        <section class="content"><div><article class="panel"><div class="panel-title"><h3>Operations flow</h3><a href="#">View pipeline →</a></div><div class="flow"><div class="step"><div class="dot">12</div><b>New leads</b><span>Needs assignment</span></div><div class="step"><div class="dot">8</div><b>Evaluations</b><span>In progress</span></div><div class="step"><div class="dot">31</div><b>Listings</b><span>Ready to market</span></div><div class="step"><div class="dot">7</div><b>Viewings</b><span>Today</span></div><div class="step"><div class="dot">4</div><b>Closing</b><span>Awaiting action</span></div></div></article><article class="panel" style="margin-top:20px"><div class="panel-title"><h3>Today’s priorities</h3><a href="#">Open tasks →</a></div><ul class="list"><li><i class="dot-status"></i><div class="item-copy"><b>Approve Al Mouj apartment for website publication</b><span>Property #RE-1048 · Marketing team</span></div><span class="pill">Approval</span></li><li><i class="dot-status gold"></i><div class="item-copy"><b>Follow up on valuation report for Al Khuwair villa</b><span>Client: Noura Al Balushi · Due today</span></div><span class="pill">Due today</span></li><li><i class="dot-status green"></i><div class="item-copy"><b>Confirm lease signing with A. Rahman</b><span>Unit 604, Qurum Heights · 2:00 PM</span></div><span class="pill">Viewing</span></li></ul></article></div><div><article class="panel"><div class="panel-title"><h3>Quick actions</h3></div><div class="quick"><a href="#"><div class="quick-icon">＋</div><strong>New lead</strong><span>Add an enquiry</span></a><a href="#"><div class="quick-icon">⌂</div><strong>Add property</strong><span>Build inventory</span></a><a href="#"><div class="quick-icon">◈</div><strong>Request evaluation</strong><span>Start valuation</span></a><a href="#"><div class="quick-icon">✉</div><strong>Compose email</strong><span>Choose mailbox</span></a></div></article><article class="panel" style="margin-top:20px"><div class="panel-title"><h3>Your companies</h3><a href="#">Manage →</a></div><div class="company-row"><div class="company-badge marketing">M</div><div><b>Riwaq Marketing</b><span>16 active campaigns</span></div><span class="status">Active</span></div><div class="company-row"><div class="company-badge valuation">V</div><div><b>Riwaq Valuation</b><span>8 reports in progress</span></div><span class="status">Active</span></div><div class="company-row"><div class="company-badge realty">R</div><div><b>Riwaq Realty</b><span>128 managed properties</span></div><span class="status">Active</span></div></article></div></section>
    </main>
</div>
</body>
</html>
